private long calculateMaxDifferenceSum(int[] A) {
    long totalSum = 0;
    int n = A.length;
    for (int i = 0; i < n - 1; i++) {
        for (int j = i + 1; j < n; j++) {
            int difference = A[j] - A[i];
            if (difference > 0) {
                totalSum += difference;
            }
        }
    }
    return totalSum;
}
